  risk:[['Credit and liquidity risks','An issuer can fail to repay and some instruments may be difficult to sell quickly without affecting price.'],['Costs and inflation','Compare returns only after understanding fees, taxes and the erosion of purchasing power.'],['When not to act','If a product is unclear or a loss would jeopardize essential expenses, more learning and independent advice may be needed.']],
  scams:[['Fake applications','Cloned trading apps can show imaginary profits then demand extra payments for withdrawals. Verify apps on official sources.'],['Social engineering','Fear, urgency and authority claims can manipulate people even when a message looks professional.'],['Response steps','Stop contact, use independently verified provider details and report suspected cybercrime promptly as appropriate.']],
  rights:[['Know your documents','Keep copies of relevant account documents and official DP statements in a secure place.'],['SCORES versus cybercrime','SEBI SCORES relates to eligible securities grievances; cybercrime.gov.in and 1930 concern suspected cybercrime.'],['Dispute resolution','SMART ODR can apply in eligible securities-market disputes subject to its current procedures.']],
