for(const lang of Object.keys(targetExamples))for(const persona of Object.keys(targetExamples[lang]))Object.assign(personalExamples[lang][persona],targetExamples[lang][persona]);
const defaultState=()=>({onboarded:false,stage:'persona',persona:'student',lang:'en',big:false,contrast:false,assessed:false,diag:{},skills:{},completed:[],scamResults:{},points:0,activity:[],setupDone:[]});
let state=load(), page=state.onboarded?'home':'onboard',activeLesson='basics',activeScenario='otp',lessonAnswer=null,lessonChecked=false,scenarioAnswer=null,scenarioChecked=false,dialog=false,chat=[{mine:false,en:labels.en.guide_welcome,hi:labels.hi.guide_welcome}];
const app=document.getElementById('app');
function load(){try{const s=JSON.parse(localStorage.getItem(STORE));return s&&typeof s==='object'?{...defaultState(),...s}:defaultState();}catch{return defaultState();}}
function save(){try{localStorage.setItem(STORE,JSON.stringify(state))}catch{}}
function t(k){return (labels[state.lang]||labels.en)[k]||labels.en[k]||k}
function c(obj){return obj[state.lang]||obj.en}
function esc(s){return String(s).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function pct(n){return Math.max(0,Math.min(100,Math.round(n)))}
function record(kind,id,correct){state.activity=[{kind,id,correct:!!correct,time:new Date().toISOString()},...state.activity].slice(0,35);save()}
function status(id){return state.completed.includes(id)}
function skill(id){return Number.isFinite(state.skills[id])?pct(state.skills[id]):0}
function totalSafe(){return Object.values(state.scamResults).reduce((acc,r)=>({right:acc.right+(r.right||0),tries:acc.tries+(r.tries||0)}),{right:0,tries:0})}
function recommendation(){const left=modules.filter(x=>!status(x.id));const candidate=left.length?left:modules;const rank=personas[state.persona].focus;return [...candidate].sort((a,b)=>{let ap=rank.indexOf(a.id),bp=rank.indexOf(b.id);ap=ap<0?rank.length:ap;bp=bp<0?rank.length:bp;let as=skill(a.id)*.68+ap*6,bs=skill(b.id)*.68+bp*6;return as-bs})[0]}
function recomReason(m){return skill(m.id)?t('recommend_reason_low'):t('recommend_reason_zero')}
function progressBar(value){return `<div class="progress-track" role="meter" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct(value)}"><div class="progress-fill" style="width:${pct(value)}%"></div></div>`}
function iconFor(id){return ({home:'⌂',learn:'▤',scam:'♢',skills:'◉',guide:'✦',resources:'↗',settings:'⚙',setup:'▣',about:'ⓘ'})[id]}
function navButtons(){let nav=['home','learn','scam','skills','guide','setup','resources','about','settings'];return nav.map(id=>`<button class="nav-btn ${page===id||((page==='lesson'&&id==='learn')||(page==='scenario'&&id==='scam'))?'active':''}" data-action="nav" data-id="${id}"><span aria-hidden="true" class="nav-icon">${iconFor(id)}</span><span>${t('nav_'+id)}</span>${id==='learn'?'<span class="nav-fill"></span>':''}</button>`).join('')}
function shell(body){return `<div class="app-shell"><aside class="sidebar" aria-label="Main navigation"><a href="#" class="brand" data-action="nav" data-id="home"><span class="logo">N.</span><span><span class="brand-name">NiveshPath</span><span class="brand-sub">Learn • Verify • Grow</span></span></a><div class="nav-label">${t('menu')}</div><nav>${navButtons()}</nav><div class="sidebar-foot"><span class="tiny-dot"></span><b style="font-size:.8rem">${t('demo')}</b><p>${t('no_advice')}</p></div></aside><div class="main-area"><header class="topbar"><span class="breadcrumb">NiveshPath <span aria-hidden="true" style="margin:0 8px;color:#a9b8b8">/</span> ${t('your_path')}</span><div class="topbar-actions"><button class="lang-btn" data-action="language" aria-label="Change language">◎ ${t('language')}</button><button class="icon-btn" data-action="toggle-big" title="${t('type')}" aria-label="${t('type')}">A+</button><button class="icon-btn" data-action="settings" title="${t('contrast')}" aria-label="${t('contrast')}">⚙</button></div></header><main id="main" class="content" tabindex="-1">${body}<div class="bottom-disclaimer">${t('footer')} <button class="inline-link" data-action="nav" data-id="about">About team and roadmap →</button></div></main></div><nav class="mobile-nav" aria-label="Mobile navigation">${['home','learn','scam','skills','guide','resources'].map(id=>`<button data-action="nav" data-id="${id}" class="${page===id||(page==='lesson'&&id==='learn')||(page==='scenario'&&id==='scam')?'active':''}"><span aria-hidden="true">${iconFor(id)}</span>${t('nav_'+id)}</button>`).join('')}</nav></div>${dialog?resetModal():''}`}
function onboarding(){const phase=state.stage==='quiz'?'quiz':'persona';if(phase==='persona')return `<div class="onboarding-wrap"><div class="stepper"><span class="step-pill active"></span><span class="step-pill"></span><span class="step-pill"></span></div><div class="white-card onboarding-card"><span class="eyebrow">INVESTOR CAPABILITY LAB · INDIA</span><h1>${t('welcome')}</h1><p class="tagline">${t('welcome_sub')}</p><h2 style="font-size:1.45rem;margin-top:24px">${t('person')}</h2><p class="muted">${t('person_hint')}</p><div class="persona-grid">${Object.entries(personas).map(([key,val])=>`<button class="choice-card ${state.persona===key?'selected':''}" data-action="persona" data-id="${key}" aria-pressed="${state.persona===key}"><span class="choice-icon">${val.icon}</span><b>${t(key)}</b><small>${t(key+'_desc')}</small></button>`).join('')}</div><div class="form-row"><div><label for="onboard-lang">${t('learning_language')}</label><select id="onboard-lang"><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="hi" ${state.lang==='hi'?'selected':''}>हिन्दी</option></select></div><div class="soft-info" style="flex:1">🔒 ${t('privacy_inline')}</div></div><div class="step-footer"><span class="muted small">${t('no_advice')}</span><button class="primary-btn" data-action="onboard-quiz">${t('continue')} <span aria-hidden="true">→</span></button></div></div></div>`;
const idx=Object.keys(state.diag).length<3?Object.keys(state.diag).length:3;const question=diagnostic[idx];if(!question)return resultOnboard();const d=c(question);return `<div class="onboarding-wrap"><div class="stepper"><span class="step-pill active"></span><span class="step-pill active"></span><span class="step-pill"></span></div><div class="white-card onboarding-card"><span class="eyebrow">${t('check')}</span><h1 style="font-size:2.05rem;margin:10px 0">${t('check')}</h1><p class="muted">${t('check_desc')}</p><div class="quiz-card" style="padding:15px 0 0"><div class="quiz-progress"><span>${t('question')} ${idx+1} ${t('of')} 3</span><span>${Math.round(idx/3*100)}%</span></div>${progressBar(idx/3*100)}<h2>${d.q}</h2><div class="answer-list">${d.opts.map((x,i)=>`<button class="answer" data-action="diagnostic-answer" data-id="${i}"><span class="answer-prefix">${String.fromCharCode(65+i)}</span><span>${x}</span></button>`).join('')}</div></div><div class="step-footer"><span class="muted small">${t('diagnostic_note')}</span><button class="text-btn" data-action="onboard-back">← ${t('back')}</button></div></div></div>`}
function resultOnboard(){return `<div class="onboarding-wrap"><div class="white-card onboarding-card" style="text-align:center"><span style="font-size:4rem">✦</span><div class="eyebrow" style="margin-top:12px">${t('personal')}</div><h1 style="font-size:2.4rem;margin:13px auto;max-width:570px">${t('welcome')}</h1><p class="muted" style="max-width:560px;margin:0 auto 24px">${t('diagnostic_note')}</p><div class="grid-two" style="max-width:680px;margin:0 auto 25px;grid-template-columns:1fr 1fr">${['demat','scams'].map(id=>`<div class="white-card pad-card"><span class="eyebrow">${esc(c(modules.find(m=>m.id===id)).title)}</span><div style="font:800 2.5rem Outfit;margin-top:8px">${skill(id)}%</div></div>`).join('')}</div><button class="primary-btn" data-action="finish-onboarding">${t('start')} →</button></div></div>`}
function stats(){let r=totalSafe();return `<div class="statistics"><div class="white-card stat"><div class="stat-icon">◉</div><div class="value">${state.completed.length}<small style="font-size:1rem;color:#9cabad"> / ${modules.length}</small></div><div class="description">${t('completed')}</div></div><div class="white-card stat"><div class="stat-icon">♢</div><div class="value">${r.tries?Math.round(r.right/r.tries*100)+'%':'—'}</div><div class="description">${t('safety')}</div></div><div class="white-card stat"><div class="stat-icon">✦</div><div class="value">${state.points}</div><div class="description">${t('points')}</div></div></div>`}
function moduleCard(m){let done=status(m.id);return `<article class="white-card module-card"><div class="topic-icon" aria-hidden="true">${m.icon}</div><span class="module-tag">${m.minutes} MIN · ${m.category==='cyber'?t('scam_type'):m.category==='decision'?t('risk_type'):m.category==='rights'?'INVESTOR RIGHTS':m.category==='foundation'?'MONEY FOUNDATIONS':'SECURITIES EDUCATION'}</span><h3>${c(m).title}</h3><p>${c(m).short}</p><div class="module-footer"><span class="chip ${done?'':'grey'}">${done?'✓ '+t('mastered'):t('not_started')}</span><button class="text-btn" data-action="lesson" data-id="${m.id}">${done?t('replay'):t('open')} ↗</button></div></article>`}
function home(){const m=recommendation(),score=skill(m.id);return `<section class="hero"><div class="hero-content"><span class="eyebrow">✧ ${t('personal')}</span><h1>${t('hello')}</h1><p>${t('hello_sub')}</p><button class="primary-btn" data-action="lesson" data-id="${m.id}">${t('resume')} <span aria-hidden="true">→</span></button></div><div class="hero-art" aria-hidden="true"><div class="hero-art-inner">✓</div><div class="art-spark one">✧</div><div class="art-spark two">✦</div></div></section>${stats()}${questPanel()}<section class="grid-two"><div class="white-card pad-card"><div class="section-heading"><div><h2>${t('recommended')}</h2><p>${t('recommended_sub')}</p></div><span class="chip">${t('reco')}</span></div><div class="recommendation"><div class="topic-icon">${m.icon}</div><div><div class="eyebrow">${m.minutes} MIN · ${state.completed.length===modules.length?t('replay'):t('practice')}</div><h3>${c(m).title}</h3><p>${c(m).short}</p><div class="hint"><b>${t('path_reason')}:</b> ${recomReason(m)}</div><button class="primary-btn" data-action="lesson" data-id="${m.id}">${t('learn_more')} →</button><div class="focus-meter">${progressBar(score)}<span>${score}%</span></div></div></div></div><div class="white-card pad-card"><div class="section-heading"><div><h2>${t('skills')}</h2><p>${t('skill_desc')}</p></div></div><div class="skills">${personas[state.persona].focus.slice(0,4).map(id=>{let md=modules.find(m=>m.id===id);return `<div class="skill-row"><div class="skill-row-head"><span>${c(md).title}</span><span>${skill(id)}%</span></div>${progressBar(skill(id))}</div>`}).join('')}</div><button class="text-btn" style="margin-top:20px" data-action="nav" data-id="skills">${t('nav_skills')} ↗</button></div></section><section><div class="section-heading"><div><h2>${t('learning')}</h2><p>${t('all_modules_sub')}</p></div><button class="text-btn" data-action="nav" data-id="learn">${t('view_all')} →</button></div><div class="module-grid">${personas[state.persona].focus.slice(0,3).map(id=>modules.find(x=>x.id===id)).filter(Boolean).map(moduleCard).join('')}</div></section><section class="section-callout"><div><div class="eyebrow">PRACTISE SAFETY</div><h3>${t('try_scam')}</h3><p>${t('try_scam_sub')}</p></div><button class="primary-btn" data-action="nav" data-id="scam">${t('open_lab')} →</button></section>`}
function learn(){const ordered=[...modules].sort((a,b)=>{let focus=personas[state.persona].focus;return (focus.indexOf(a.id)<0?999:focus.indexOf(a.id))-(focus.indexOf(b.id)<0?999:focus.indexOf(b.id))});return `<div class="page-heading"><div><span class="eyebrow">CURATED LEARNING PATHS</span><h1>${t('all_modules')}</h1><p>${t('all_modules_sub')}</p></div><span class="chip">${state.completed.length}/${modules.length} ${t('mastered')}</span></div><div class="journey-banner"><span class="eyebrow">PERSONALISED JOURNEY</span><h2>${t(state.persona)} · ${state.persona==='student'?'Money habits → Financial foundations → Investor safety':state.persona==='newcomer'?'Investing concepts → Demat procedures → Informed decisions':'Fraud defence → Long-term security → Rights & records'}</h2><p>All lessons remain available. The displayed order is intentionally different for each learner group.</p></div><section class="module-grid">${ordered.map(moduleCard).join('')}</section><section class="section-callout"><div><h3>${t('try_scam')}</h3><p>${t('try_scam_sub')}</p></div><button class="secondary-btn" data-action="nav" data-id="scam">${t('open_lab')} →</button></section>`}
function sourceLink(id){let name=sources.find(x=>x.url===id)?.name||'Official resource';return `<a href="${OFFICIAL[id]||OFFICIAL.investor}" target="_blank" rel="noopener noreferrer">${esc(name)} ↗</a>`}
function lesson(){let m=modules.find(x=>x.id===activeLesson)||modules[0],d=c(m),checked=lessonChecked&&lessonAnswer!==null,correct=checked&&Number(lessonAnswer)===d.right;return `<div><button class="back-btn" data-action="nav" data-id="learn">← ${t('back')}</button><div class="lesson-header"><div class="eyebrow" style="color:#99e6d3">${m.minutes} MIN · ${t('teach')}</div><h1>${d.title}</h1><p>${d.intro}</p><button class="ghost-btn" data-action="speak" style="margin-top:20px">▷ ${t('read')}</button></div>${state.lang==='hi' && EXTRA_MODULES.some(x=>x.id===m.id)?'<div class="soft-info" style="margin-bottom:12px">विस्तृत पाठ अभी अंग्रेज़ी में है; हिंदी शीर्षक और सारांश उपलब्ध हैं। पूर्ण हिंदी अनुवाद भविष्य के विकास में प्रस्तावित है।</div>':''}<div class="soft-info" style="margin-bottom:20px"><b>✧ ${t('personal')}</b> · ${personalExamples[state.lang][state.persona][m.id]}</div><div class="grid-two"><div><div class="lesson-concepts">${d.concepts.map((v,i)=>`<article class="white-card concept-card"><div class="concept-bullet">${i+1}</div><div><h3>${v[0]}</h3><p>${v[1]}</p></div></article>`).join('')}</div><div class="soft-info" style="margin-top:15px">${t('source')}: ${sourceLink(m.source)}. ${t('no_advice')}</div></div><aside><div class="white-card quiz-card"><span class="eyebrow">${t('lesson_question')}</span><h2>${d.q}</h2><div class="answer-list">${d.opts.map((x,i)=>`<button class="answer ${lessonAnswer===i?'selected':''} ${checked&&i===d.right?'correct':''} ${checked&&i===lessonAnswer&&!correct?'incorrect':''}" data-action="lesson-answer" data-id="${i}" ${checked?'disabled':''} aria-pressed="${lessonAnswer===i}"><span class="answer-prefix">${String.fromCharCode(65+i)}</span><span>${x}</span></button>`).join('')}</div>${checked?`<div class="feedback ${correct?'':'warning'}" role="status"><b>${t(correct?'well_done':'review')}</b><p>${d.explain}</p></div><div class="step-footer"><button class="${correct?'primary-btn':'secondary-btn'}" data-action="${correct?'nav':'retry-lesson'}" data-id="learn">${t(correct?'next_module':'try_again')} →</button></div>`:`<div class="step-footer"><span class="muted small">${t('select')}</span><button class="primary-btn" data-action="check-lesson" ${lessonAnswer===null?'disabled':''}>${t('submit')}</button></div>`}</div>${correct?`<div class="white-card pad-card" style="margin-top:15px"><div class="eyebrow">✦ ${t('lesson_complete')}</div><p style="margin:8px 0 0">${t('lesson_complete_desc')}</p></div>`:''}</aside></div></div>`}
function scam(){return `<div class="page-heading"><div><span class="eyebrow">SAFE DECISION SIMULATIONS</span><h1>${t('lab')}</h1><p>${t('lab_sub')}</p></div><span class="chip orange">${Object.keys(state.scamResults).length}/${scenarios.length} ${t('scenario_completed')}</span></div><section class="scenario-grid">${scenarios.map((s,i)=>`<article class="white-card scenario-card"><div class="topic-icon">${s.icon}</div><div class="module-tag">${t('scenario')} ${String(i+1).padStart(2,'0')}</div><h3>${c(s).title}</h3><p>${c(s).short}</p><button class="secondary-btn" data-action="scenario" data-id="${s.id}">${t('practice')} →</button></article>`).join('')}</section><section class="soft-info">${t('note')}</section>`}
function scenario(){let s=scenarios.find(x=>x.id===activeScenario)||scenarios[0],d=c(s),checked=scenarioChecked&&scenarioAnswer!==null,correct=checked&&Number(scenarioAnswer)===d.right;return `<button class="back-btn" data-action="nav" data-id="scam">← ${t('scenario_home')}</button><div class="grid-two"><div><div class="lesson-header"><span class="eyebrow" style="color:#99e6d3">SIMULATION · ${t('scam_type')}</span><h1>${d.title}</h1><p>${d.short}</p><button class="ghost-btn" data-action="speak" style="margin-top:18px">▷ ${t('read')}</button></div><div class="white-card pad-card"><span class="eyebrow">FICTIONAL EXAMPLE · NO REAL MESSAGE</span><div class="fake-message"><div class="sender">${d.from}</div>${esc(d.story)}</div><p class="muted small" style="margin-bottom:0">${t('source')}: ${sourceLink(s.source)}</p></div></div><div><div class="white-card quiz-card"><span class="eyebrow">${t('choose')}</span><h2 style="font-size:1.4rem">${t('choose')}</h2><div class="answer-list">${d.options.map((x,i)=>`<button class="answer ${scenarioAnswer===i?'selected':''} ${checked&&i===d.right?'correct':''} ${checked&&i===scenarioAnswer&&!correct?'incorrect':''}" data-action="scenario-answer" data-id="${i}" ${checked?'disabled':''} aria-pressed="${scenarioAnswer===i}"><span class="answer-prefix">${String.fromCharCode(65+i)}</span><span>${x}</span></button>`).join('')}</div>${checked?`<div class="feedback ${correct?'':'warning'}" role="status"><b>${t(correct?'safe':'needs_work')}</b><p>${d.explain}</p></div><div class="soft-info" style="margin-top:14px"><b>${t('tip')}:</b> ${d.tip}</div><div class="step-footer"><button class="secondary-btn" data-action="nav" data-id="scam">${t('scenario_home')}</button><button class="primary-btn" data-action="next-scenario">${t('another')} →</button></div>`:`<div class="step-footer"><span class="muted small">${t('select')}</span><button class="primary-btn" data-action="check-scenario" ${scenarioAnswer===null?'disabled':''}>${t('submit')}</button></div>`}</div></div></div>`}
function skills(){let r=totalSafe();return `<div class="page-heading"><div><span class="eyebrow">LEARN, PRACTISE, RETAIN</span><h1>${t('nav_skills')}</h1><p>${t('skill_history_desc')}</p></div><span class="chip">${t('level')}: ${state.completed.length<=1?t('beginner'):state.completed.length<Math.ceil(modules.length/4)?t('exploring'):t('ready')}</span></div>${stats()}<section class="grid-two"><div class="white-card pad-card"><div class="section-heading"><h2>${t('knowledge')}</h2></div><div class="skills">${modules.map(m=>`<div class="skill-row"><div class="skill-row-head"><span>${c(m).title}</span><span>${skill(m.id)}%</span></div>${progressBar(skill(m.id))}</div>`).join('')}</div><div class="soft-info" style="margin-top:23px">${t('skill_history_desc')}</div></div><div class="white-card pad-card"><div class="section-heading"><h2>${t('next_milestones')}</h2></div>${[['m1','m1d',state.assessed,'✧'],['m2','m2d',state.completed.length>=2,'🏅'],['m3','m3d',r.right>=3,'🛡']].map(([a,b,done,icon])=>`<div class="badge-showcase"><div class="award" aria-hidden="true">${icon}</div><div><b>${t(a)} ${done?'✓':''}</b><p>${t(b)}</p></div></div>`).join('')}${extraBadges()}<div class="section-heading" style="margin-top:27px"><h2>${t('activity')}</h2></div>${state.activity.length?state.activity.slice(0,5).map(a=>`<div class="milestone"><div class="mini-symbol">${a.correct?'✓':'↺'}</div><div><b>${a.kind==='lesson'?c(modules.find(m=>m.id===a.id)||modules[0]).title:c(scenarios.find(s=>s.id===a.id)||scenarios[0]).title}</b><span>${a.correct?t('well_done'):t('review')}</span></div></div>`).join(''):`<p class="muted">${t('no_activity')}</p>`}</div></section>`}
function guideResponse(input){
 const q=input.toLowerCase().trim();const hi=state.lang==='hi';
 if(/\b(pan|aadhaar|aadhar|password|otp|pin|account number|bank account|ifsc|cvv)\b/.test(q)&&/\d{5,}/.test(q))return 'Please do not submit personal identity, account or access information here. This educational prototype cannot process or verify it. Clear this chat or reset the demo if you entered sensitive information.';
 if(/\b(buy|sell|stock tip|which stock|best stock|recommend|portfolio allocation|target price|price target|prediction|give me a trade|invest in|multibagger)\b|कौन सा शेयर|खरीद|बेच|निवेश करूँ/.test(q))return hi?'मैं शेयर की सलाह, कीमत का अनुमान या ट्रेडिंग निर्देश नहीं दे सकता। SEBI Investor की आधिकारिक शिक्षा सामग्री देखें।':'I cannot provide personalized investment advice, security recommendations, price forecasts or execution instructions. I can explain risks, product structures, investor rights and how to verify claims. Use official SEBI learning sources.';
 const bank=[
 [/save|saving|budget|expense|emergency|needs|wants|बचत|बजट/, 'Start by distinguishing essential needs from optional spending, recording cash inflows and outflows, and planning for an accessible emergency buffer. Budgeting and managing expensive borrowing often come before accepting market risk. Open “Why saving comes first” or the free NISM Investor Education course.'],
 [/why invest|investing|inflation|compound|return|महँगाई|निवेश|चक्रवृद्धि/, 'Investing may help some long-term goals but it is not compulsory. Inflation can reduce purchasing power; compounding can magnify growth and losses. Time horizon, emergency needs and your ability to absorb losses matter. No return is guaranteed. Review “Why people consider investing” and “Inflation and purchasing power”.'],
 [/open|start.*account|kyc|new account|how.*demat|डीमैट खाता कैसे/, 'To understand opening a demat account: 1) Find a registered DP using the official CDSL site. 2) Compare its charges and services. 3) Use that DP’s verified KYC process. 4) Read rights, fees, authorizations and nomination details. 5) Confirm account and alerts. Never submit PAN, documents, OTP or passwords on NiveshPath. Open “Start with a demat” for the seven-step walkthrough.'],
 [/demat|depository|depository participant|\bdp\b|cdsl|nsdl|डीमैट|डिपॉजिटरी/, 'A demat account holds eligible securities electronically. CDSL and NSDL maintain depository records; a Depository Participant services the investor’s account, while a broker provides trading access. CDSL does not open a demat account directly for investors. Verify your DP through the official CDSL/NSDL websites.'],
 [/share|equity|stock exchange|\bnse\b|\bbse\b|primary market|secondary|ipo/, 'A share generally represents company ownership and carries market risk. The primary market is where securities are issued; secondary markets facilitate trading in existing securities. NSE and BSE are exchanges, clearing corporations manage settlement obligations, and depositories record electronic holdings. See “How NSE, BSE and clearing work”.'],
 [/bond|coupon|yield|interest.rate|g.sec|government securit/, 'A bond is generally a debt claim on an issuer. Coupon, yield, maturity, credit risk, interest-rate risk and liquidity are distinct. A high advertised yield can reflect additional risk; repayment depends on contractual terms and the issuer’s ability to pay. See “Bonds, interest and credit risk”.'],
 [/mutual|fund|etf|index fund|diversif/, 'Mutual funds pool investors’ money under defined mandates; ETFs are traded on an exchange. Both can lose value and charge fees. Diversification can reduce some concentration risk but cannot eliminate general market risk. Review official fund documents for terms and costs.'],
 [/fraud|scam|phish|otp|fake|upi|cyber|app|whatsapp|impersonat|ठगी|फर्जी|धोखा|साइबर/, 'Stop if someone pressures you, guarantees large profits, requests OTP/PIN/password, demands a fee to release “profits”, or asks you to install a private APK or remote-access app. Verify through independently typed official URLs. If you suspect cybercrime in India, consult cybercrime.gov.in or call 1930 as appropriate. Use the Fraud Defence Lab to practise.'],
 [/complain|grievance|scores|odr|report|helpline|शिकायत/, 'For an eligible securities-market service grievance, first contact the concerned regulated entity through its official grievance process. SEBI SCORES and, where applicable, SMART ODR support additional procedures. For suspected cybercrime, use cybercrime.gov.in or India’s 1930 helpline. These are different routes.'],
 [/nomination|nominee|transmission|dividend|corporate action|inherit|estate/, 'Nomination, transmission, dividends, rights and other corporate actions have distinct legal procedures. Check the current CDSL Investor Charter and confirm steps with your DP. Do not send sensitive documents or secrets to unsolicited contacts.'],
 [/senior|retire|pension|old age|healthcare/, 'For long-term security, learn about essential spending, healthcare uncertainty, inflation, access to savings, official nomination records and digital impersonation risks. See the senior-citizen pathway and “Long-term security and retirement basics”.'],
 [/module|lesson|course|learn|website|resource|source/, 'Choose “Learning journeys” for a personalized path, or “Safety & resources” for curated official SEBI, CDSL, NSDL, NISM, NSE and BSE sources. Lessons are educational and all modules are accessible to everyone.']
 ];
 const found=bank.find(([re])=>re.test(q));return found?found[1]:(hi?'मैं इस शैक्षिक प्रोटोटाइप में बचत, वित्तीय साधन, डीमैट, जोखिम, साइबर सुरक्षा और शिकायत पर मदद कर सकता हूँ। एक विषय पर छोटा प्रश्न पूछें।':'I can help with savings, investing fundamentals, financial instruments, demat steps, securities infrastructure, risk, cybersecurity and investor rights. Please ask one clear educational question. For current official rules, use the verified resource links.');
}
function guide(){return `<div class="page-heading"><div><span class="eyebrow">EXPLAINABLE, GUARDED GUIDANCE</span><h1>${t('guide')}</h1><p>${t('guide_sub')}</p></div></div><div class="grid-two"><div class="white-card advisor"><div class="messages" id="chat-messages" role="log" aria-live="polite" aria-label="Learning guide conversation">${chat.map(m=>`<div class="message ${m.mine?'mine':''}">${esc(m.mine?m.text:m[state.lang])}</div>`).join('')}</div><div class="chat-bottom"><div class="prompts">${['guide_prompt1','guide_prompt2','guide_prompt3'].map(key=>`<button class="prompt-chip" data-action="prompt" data-id="${key}">${t(key)}</button>`).join('')}</div><form class="chat-form" id="chat-form"><label class="visually-hidden" for="chat-input">${t('ask_placeholder')}</label><input id="chat-input" maxlength="240" autocomplete="off" placeholder="${t('ask_placeholder')}" required /><button class="primary-btn" type="submit">${t('send')} →</button></form></div></div><aside><div class="white-card pad-card"><span class="eyebrow">RULE-BASED EDUCATION GUIDE</span><h2>${t('guide')}</h2><p class="muted">${t('guide_notice')}</p><div class="soft-info">🔐 ${t('data_title')}: ${t('privacy_inline')}</div><div style="margin-top:25px"><b>${t('source')}</b><div class="source-list" style="margin-top:12px">${sources.slice(0,3).map(x=>`<a class="source-link white-card" href="${OFFICIAL[x.url]}" target="_blank" rel="noopener noreferrer"><span><b>${x.name}</b></span><span>↗</span></a>`).join('')}</div></div></div></aside></div>`}
function resources(){
 const groups=['Getting started','Learning','Depositories','Exchanges','Safety'];
 return `<div class="page-heading"><div><span class="eyebrow">OFFICIAL SOURCES · VERIFIED 28 OCT 2026</span><h1>${t('resources')}</h1><p>Organized primary sources, clearly separated from this independent learning prototype.</p></div></div>
 <section class="section-callout"><div><h3>⚠ ${t('safety_now')}</h3><p>${t('safety_now_desc')}</p></div><a class="primary-btn" href="${OFFICIAL.cyber}" target="_blank" rel="noopener noreferrer">Report cybercrime ↗</a></section>
 <section class="white-card pad-card"><div class="section-heading"><h2>Start here: Official demat account information</h2><button class="primary-btn" data-action="nav" data-id="setup">Step-by-step guide →</button></div><p>CDSL is a depository, not a trading app. Open an account only with a SEBI-registered Depository Participant, not through NiveshPath.</p></section>
 ${groups.map(group=>`<section class="resource-group"><div class="section-heading"><h2>${group}</h2></div><div class="resource-grid">${sources.filter(x=>x.group===group).map(s=>`<a class="source-link white-card" href="${esc(OFFICIAL[s.url])}" target="_blank" rel="noopener noreferrer"><span><b>${esc(s.name)}</b><small>${esc(state.lang==='hi'?s.hi:s.text)}</small><span class="resource-domain">${esc(new URL(OFFICIAL[s.url]).hostname)}</span></span><span aria-hidden="true">↗</span></a>`).join('')}</div></section>`).join('')}
 <div class="soft-info">Primary-source links open third-party websites. Their availability and content may change. NiveshPath is not partnered with, endorsed by or a login portal for any listed institution. We do not fetch or collect information from these websites.</div>`
}
function setup(){
 const steps=[
 ['Understand the purpose','A demat account records eligible securities electronically; you do not need one just to learn investing. A trading account and a bank account have different functions.'],
 ['Choose an official Depository Participant (DP)','Use the official CDSL DP search and tariff information. Compare costs and services. Do not use account-opening links from unsolicited calls or messages.'],
 ['Prepare information securely','A registered DP may request PAN, identity and address proof, registered phone/email, bank information and prescribed KYC details. Never type any of these into NiveshPath.'],
 ['Complete DP-controlled KYC','Follow the registered DP’s own verified portal or branch process and any required identity or video verification. Do not permit someone else to operate your device.'],
 ['Read rights, charges and authorizations','Understand the DP tariff, rights and obligations, nomination choices, and any voluntary permissions before you agree. Never sign blank forms.'],
 ['Check the account confirmation','Once the DP has completed its process, verify the account details and contact information using its official communication channels.'],
 ['Maintain safe habits','Protect login secrets and e-DIS PINs, check account statements and transaction alerts, and escalate unrecognized activity immediately.']
 ];
 return `<div class="page-heading"><div><span class="eyebrow">ACCESSIBLE, NON-TRANSACTIONAL GUIDE</span><h1>Understand how to open a demat account</h1><p>Seven educational steps, with no form, no personal data and no account opening on this website.</p></div></div>
 <section class="soft-info"><b>Important distinction:</b> CDSL/NSDL are depositories. Investors open demat accounts through registered Depository Participants. NiveshPath never collects PAN, Aadhaar, bank details, OTPs, credentials or identity documents.</section>
 <section class="white-card pad-card" style="margin-top:18px"><div class="section-heading"><h2>Guided preparation checklist</h2><span class="chip" id="setup-counter">0 / 7 reviewed</span></div><p class="muted">Mark a step when you have understood it. Checking boxes does not open an account or confirm eligibility.</p><div class="setup-steps">${steps.map((v,i)=>`<label class="setup-step"><input type="checkbox" data-action="setup-check" data-id="${i}" ${state.setupDone?.includes(i)?'checked':''}/><span class="concept-bullet">${i+1}</span><span><b>${v[0]}</b><small>${v[1]}</small></span></label>`).join('')}</div><div class="soft-info">After reviewing: Visit <a href="${OFFICIAL.cdslOpen}" target="_blank" rel="noopener noreferrer">CDSL's official DP account-opening guide ↗</a> or <a href="${OFFICIAL.sebiReading}" target="_blank" rel="noopener noreferrer">SEBI's KYC learning material ↗</a>. Never share information on this demo.</div></section>
 <section class="white-card pad-card" style="margin-top:18px"><h2>When to contact whom</h2><div class="step-compare"><div><b>DP</b><p>Account opening, changes, statements, fees and direct service issues.</p></div><div><b>CDSL or NSDL</b><p>Depository-specific education, records infrastructure and applicable escalation.</p></div><div><b>SEBI SCORES / SMART ODR</b><p>Applicable eligible grievance or dispute escalation, following relevant procedures.</p></div><div><b>Cybercrime Portal / 1930</b><p>Suspected cybercrime or online financial fraud in India.</p></div></div></section>`
}
function about(){return `<div class="page-heading"><div><span class="eyebrow">TEAM MDI INNOVATORS · MDI GURGAON</span><h1>About NiveshPath</h1><p>Learn · Verify · Grow. An educational website prototype for the CDSL Reimagine Ideathon.</p></div></div>
 <section class="white-card pad-card"><h2>Why we built it</h2><p>NiveshPath explores how investor education can become practical and accessible for students, first-time investors and senior citizens. Our prototype combines finance and cybersecurity explainers, safe-to-fail simulations, a learning guide, official source references and learner-group pathways.</p><p><b>What works today:</b> local onboarding, learner-specific lesson ordering, knowledge quizzes, scenario choices, learning points, badges, a rule-based question assistant, accessibility controls and links to official information. This is not a brokerage, an account-opening platform or an investment adviser.</p></section>
 <section class="section-heading" style="margin-top:29px"><div><h2>Meet the team</h2><p>MDI Innovators · PGDM Banking & Financial Services</p></div></section>
 <div class="team-grid"><article class="white-card team-card"><img src="assets/jeetaksh.jpg" alt="Jeetaksh Gandhi" loading="lazy"/><h3>Jeetaksh Gandhi</h3><p class="team-role">PGDM-BFS · MDI Gurgaon</p><p>Jeetaksh is a PGDM-BFS student at MDI Gurgaon and a computer science graduate from LNMIIT Jaipur. Previously at Innovaccer and Datacurve (YC W24), he worked across data engineering, analytics, AI-related workflows and growth strategy. He is interested in fintech, product development and making investor education more practical.</p></article>
 <article class="white-card team-card"><img src="assets/sakshi.jpg" alt="Sakshi Singh" loading="lazy"/><h3>Sakshi Singh</h3><p class="team-role">PGDM-BFS · MDI Gurgaon</p><p>Sakshi is a PGDM-BFS student at MDI Gurgaon and a former Audit & Assurance professional at Deloitte USI. With a background in commerce and financial services, she is interested in financial markets, investor education, and simplifying complex financial concepts.</p></article></div>
 <section class="white-card pad-card" style="margin-top:20px"><h2>Future development roadmap</h2><div class="roadmap-grid"><div><b>Phase 1 · Content and validation</b><p>Expand the verified Hindi and regional-language curriculum; validate examples with subject-matter reviewers.</p></div><div><b>Phase 2 · AI guide</b><p>Propose retrieval-grounded AI explanations based on reviewed sources, with uncertainty handling and human oversight. <b>Not yet implemented.</b></p></div><div><b>Phase 3 · Personalization</b><p>Propose adaptive recommendations based on learning errors and optional consented progress data, without financial profiling.</p></div><div><b>Phase 4 · Impact assessment</b><p>Pilot with all three learner segments and test safe-decision skills, accessibility and knowledge retention.</p></div></div></section>
 <div class="soft-info" style="margin-top:20px">This is an educational website prototype prepared for the CDSL Reimagine Ideathon. Some future-scope features are illustrative and may not work in the present version. It is independent student work and is not affiliated with or endorsed by CDSL, NSDL, SEBI, NSE, BSE or NISM. Educational content should be revalidated before a public launch.</div>`}
function questPanel(){
 const lesson=recommendation(); const undone=scenarios.find(s=>!state.scamResults[s.id]);const reviewed=(state.setupDone||[]).length;
 return `<section class="quest-panel white-card"><div><span class="eyebrow">✨ CAPABILITY QUESTS</span><h2>Earn progress by understanding, not by trading</h2><p>Lessons award 20 points once; safe decisions award 10 once. No financial gains, trading or cash rewards.</p></div><div class="quest-actions"><button class="secondary-btn" data-action="lesson" data-id="${lesson.id}">📖 Next lesson</button><button class="secondary-btn" data-action="${undone?'scenario':'nav'}" data-id="${undone?undone.id:'scam'}">🛡 ${undone?'Safety challenge':'Review challenges'}</button><button class="secondary-btn" data-action="nav" data-id="setup">▣ Demat checklist (${reviewed}/7)</button></div><div class="quest-level"><span>Learning level ${1+Math.floor(state.points/100)}</span>${progressBar(state.points%100)}<span>${state.points%100}/100 to next level</span></div></section>`
}
function extraBadges(){let num=state.completed.length,scam=totalSafe(),checks=(state.setupDone||[]).length;return `<div class="extra-badges">${[
 ['📚','Curious learner',num>=5,'Master 5 lessons'],['🏦','Account explorer',checks>=7,'Review all 7 demat steps'],['🧠','Financial foundations', ['saving','investwhy','instruments'].every(x=>status(x)), 'Master saving, investing and instruments'],['🔐','Cyber guardian',scam.right>=5,'Make five safe practice choices'],['🏆','Capability champion',num>=10&&scam.right>=5,'Master 10 lessons and five safe scenarios']
].map(([ico,title,done,desc])=>`<div class="badge-showcase ${done?'earned':'locked'}"><div class="award">${ico}</div><div><b>${title} ${done?'✓':'🔒'}</b><p>${desc}</p></div></div>`).join('')}</div>`}
function settings(){return `<div class="page-heading"><div><span class="eyebrow">DESIGNED FOR EVERY LEARNER</span><h1>${t('settings')}</h1><p>${t('settings_sub')}</p></div></div><section class="grid-two"><div class="white-card pad-card"><h2>${t('settings')}</h2>${[['big','large_title','large_desc'],['contrast','contrast_title','contrast_desc'],['lang','hindi_title','hindi_desc']].map(([key,title,desc])=>{let checked=key==='lang'?state.lang==='hi':state[key];return `<div class="settings-row"><div><b>${t(title)}</b><p>${t(desc)}</p></div><button class="toggle ${checked?'on':''}" role="switch" aria-checked="${checked}" aria-label="${t(title)}" data-action="setting" data-id="${key}"></button></div>`}).join('')}<div class="settings-row"><div><b>${t('spoken_title')}</b><p>${t('spoken_desc')}</p></div><button class="secondary-btn" data-action="speak">${t('read')} ▷</button></div></div><div><div class="white-card pad-card"><h2>${t('data_title')}</h2><p class="muted">${t('data_title')}: ${t('privacy_inline')}</p><div class="soft-info">${t('privacy_inline')}</div><div style="margin-top:21px"><b>${t('reset_title')}</b><p class="muted small">${t('reset_desc')}</p><button class="secondary-btn" data-action="ask-reset">${t('reset')}</button></div></div><div class="soft-info" style="margin-top:15px">${t('note')}</div></div></section>`}
function resetModal(){return `<div class="modal-backdrop" role="presentation"><div role="dialog" aria-modal="true" aria-labelledby="modal-title" class="modal"><h2 id="modal-title">${t('confirm_reset')}</h2><p class="muted">${t('confirm_reset_desc')}</p><div class="step-footer"><button class="secondary-btn" data-action="close-modal">${t('cancel')}</button><button class="primary-btn" data-action="reset">${t('confirm')}</button></div></div></div>`}
function render(){document.documentElement.lang=state.lang;document.documentElement.classList.toggle('big-text',state.big);document.documentElement.classList.toggle('high-contrast',state.contrast);let pages={onboard:onboarding,home,learn,lesson,scam,scenario,skills,guide,resources,setup,about,settings};let fn=pages[page]||home;app.innerHTML=page==='onboard'?`<main id="main" class="content">${fn()}</main>${dialog?resetModal():''}`:shell(fn());document.title=`${page==='onboard'?'Welcome':page==='home'?'Dashboard':(t('nav_'+(page==='lesson'?'learn':page==='scenario'?'scam':page))||'Learning')} · NiveshPath`;if(page==='guide'){let el=document.getElementById('chat-messages');if(el)el.scrollTop=el.scrollHeight}}
function goto(where){page=where;dialog=false;render();window.scrollTo({top:0,behavior:'instant'});}
function updatePractice(kind,id,correct){let old=kind==='scenario'?state.scamResults[id]:null;if(kind==='scenario'){state.scamResults[id]={right:(old?.right||0)+(correct?1:0),tries:(old?.tries||0)+1};let related=id==='advisor'?'scams':id==='report'?'rights':'scams';state.skills[related]=pct(Math.max(skill(related),correct?80:Math.max(15,skill(related)-3)));if(correct && !(old?.right))state.points+=10;}record(kind,id,correct);save()}
function speakCurrent(){if(!('speechSynthesis'in window))return alert(state.lang==='hi'?'यह ब्राउज़र बोलने की सुविधा नहीं देता।':'Speech is not available in this browser.');let text;if(page==='lesson'){let m=c(modules.find(x=>x.id===activeLesson));text=[m.title,m.intro,...m.concepts.flat()].join('. ')}else if(page==='scenario'){let s=c(scenarios.find(x=>x.id===activeScenario));text=[s.title,s.story].join('. ')}else text=t('settings_sub');window.speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text);u.lang=state.lang==='hi'?'hi-IN':'en-IN';u.rate=.86;window.speechSynthesis.speak(u)}
function submitChat(input){let s=input.trim().slice(0,240);if(!s)return;chat.push({mine:true,text:s});let ans=guideResponse(s);chat.push({mine:false,en:ans,hi:ans});if(chat.length>30)chat=chat.slice(-30);render();}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;if(b.matches('a'))e.preventDefault();let action=b.dataset.action,id=b.dataset.id;
 switch(action){
 case 'nav':if(page==='onboard')break;goto(id);break;
 case 'settings':goto('settings');break;
 case 'language':state.lang=state.lang==='en'?'hi':'en';save();render();break;
 case 'toggle-big':state.big=!state.big;save();render();break;
 case 'persona':state.persona=id;save();render();break;
 case 'onboard-quiz':state.stage='quiz';state.diag={};save();render();break;
 case 'onboard-back':state.stage='persona';state.diag={};save();render();break;
 case 'diagnostic-answer':{let idx=Object.keys(state.diag).length;if(idx>=3)break;state.diag[idx]=Number(id);let q=diagnostic[idx];state.skills[q.skill]=Number(id)===q.right?55:15;if(Object.keys(state.diag).length===3){state.assessed=true}save();render();break;}
 case 'finish-onboarding':state.onboarded=true;save();goto('home');break;
 case 'lesson':activeLesson=id;lessonAnswer=null;lessonChecked=false;goto('lesson');break;
 case 'lesson-answer':if(!lessonChecked){lessonAnswer=Number(id);render()}break;
 case 'check-lesson':if(lessonAnswer===null)break;{let m=modules.find(x=>x.id===activeLesson),correct=lessonAnswer===c(m).right;lessonChecked=true;if(correct){if(!status(m.id)){state.completed.push(m.id);state.points+=20}state.skills[m.id]=100}else{state.skills[m.id]=pct(Math.max(skill(m.id),30));}record('lesson',m.id,correct);save();render()}break;
 case 'retry-lesson':lessonAnswer=null;lessonChecked=false;render();break;
 case 'scenario':activeScenario=id;scenarioAnswer=null;scenarioChecked=false;goto('scenario');break;
 case 'scenario-answer':if(!scenarioChecked){scenarioAnswer=Number(id);render()}break;
 case 'check-scenario':if(scenarioAnswer===null)break;{let s=scenarios.find(x=>x.id===activeScenario),correct=scenarioAnswer===c(s).right;scenarioChecked=true;updatePractice('scenario',s.id,correct);render()}break;
 case 'next-scenario':{let idx=scenarios.findIndex(x=>x.id===activeScenario);activeScenario=scenarios[(idx+1)%scenarios.length].id;scenarioAnswer=null;scenarioChecked=false;render();window.scrollTo(0,0)}break;
 case 'prompt':submitChat(t(id));break;
 case 'setup-check':{let item=Number(id);state.setupDone=state.setupDone||[]; if(b.checked){if(!state.setupDone.includes(item))state.setupDone.push(item)}else state.setupDone=state.setupDone.filter(x=>x!==item); save();render();break;}
 case 'setting':if(id==='lang')state.lang=state.lang==='en'?'hi':'en';else state[id]=!state[id];save();render();break;
 case 'speak':speakCurrent();break;
 case 'ask-reset':dialog=true;render();break;
 case 'close-modal':dialog=false;render();break;
 case 'reset':{try{localStorage.removeItem(STORE)}catch{}state=defaultState();dialog=false;chat=[{mine:false,en:labels.en.guide_welcome,hi:labels.hi.guide_welcome}];goto('onboard')}break;
 }});
document.addEventListener('change',e=>{if(e.target?.id==='onboard-lang'){state.lang=e.target.value==='hi'?'hi':'en';save();render()}});
document.addEventListener('submit',e=>{if(e.target?.id==='chat-form'){e.preventDefault();let el=document.getElementById('chat-input');if(el)submitChat(el.value)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&dialog){dialog=false;render()}});
render();

if ('serviceWorker' in navigator && /^https?:$/.test(location.protocol)) {
  window.addEventListener('load', () => navigator.serviceWorker.register('./sw.js').catch(() => {}));
}
